from scipy.optimize import least_squares
def tryform(f,p0):
    best=None
    for s in range(6):
        p=np.random.RandomState(s).randn(len(p0))*0.5+np.array(p0)
        try:
            r=least_squares(lambda q: f(q)-dP_dt, p)
            if best is None or r.cost<best.cost: best=r
        except Exception as e: pass
    return np.sqrt(np.mean(best.fun**2)), np.round(best.x,4)
